package com.me.learning.framework.service;


import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import java.util.stream.Collectors;

import org.springframework.data.relational.core.sql.Column;
import org.springframework.data.relational.core.sql.Condition;
import org.springframework.data.relational.core.sql.Conditions;
import org.springframework.data.relational.core.sql.SQL;

import com.me.learning.framework.service.filter.BaseFilter;
import com.me.learning.framework.service.filter.BoolFilter;
import com.me.learning.framework.service.filter.DurationFilter;
import com.me.learning.framework.service.filter.InstantFilter;
import com.me.learning.framework.service.filter.RangeFilter;
import com.me.learning.framework.service.filter.StrFilter;
import com.me.learning.framework.service.filter.ZonedDateTimeFilter;


/**
 * Class for constructing org.springframework.data.relational.core.sql.Condition
 * from the Entity Criteria
 *
 */
public class ConditionBuilder {

    private final List<Condition> allFilters = new ArrayList<> ();

    private final ColumnConverterReactive columnConverter;

    public ConditionBuilder (ColumnConverterReactive columnConverter) {
        this.columnConverter = columnConverter;
    }

    /**
     * Method that takes in a filter field and a column to construct a compounded SQL Condition.
     * The built condition can be retrieved using the buildConditions function
     *
     * @param <X>    Field type
     * @param field  The actual Filter field
     * @param column The column for which the condition is constructed
     */
    public <X> void buildFilterConditionForField (BaseFilter<X> field, Column column) {
        if ( field instanceof DurationFilter ) {
            buildRangeConditions ((DurationFilter) field, column, Long.class);
            buildGeneralConditions (field, column, Long.class);
        } else if ( field instanceof ZonedDateTimeFilter ) {
            buildRangeConditions ((ZonedDateTimeFilter) field, column, LocalDateTime.class);
            buildGeneralConditions (field, column, LocalDateTime.class);
        } else if ( field instanceof InstantFilter ) {
            buildRangeConditions ((InstantFilter) field, column, LocalDateTime.class);
            buildGeneralConditions (field, column, LocalDateTime.class);
        } else if ( field instanceof RangeFilter ) {
            buildRangeConditions ((RangeFilter) field, column, null);
            buildGeneralConditions (field, column, null);
        } else if ( field instanceof StrFilter ) {
            buildStringConditions ((StrFilter) field, column);
            buildGeneralConditions (field, column, null);
        } else if ( field instanceof BoolFilter ) {
            buildBooleanConditions (field, column);
        } else {
            buildGeneralConditions (field, column, null);
        }
    }

    private <X extends Comparable<? super X>> void buildRangeConditions (RangeFilter<X> rangeData, Column column, Class<?> targetClass) {
        var converterFunction = columnValueConverter (targetClass);
        if ( rangeData.getGreaterThan () != null ) {
            allFilters.add (Conditions.isGreater (column, SQL.literalOf (converterFunction.apply (rangeData.getGreaterThan ()))));
        }
        if ( rangeData.getLessThan () != null ) {
            allFilters.add (Conditions.isLess (column, SQL.literalOf (converterFunction.apply (rangeData.getLessThan ()))));
        }
        if ( rangeData.getGreaterThanOrEqual () != null ) {
            allFilters.add (
                    Conditions.isGreaterOrEqualTo (column, SQL.literalOf (converterFunction.apply (rangeData.getGreaterThanOrEqual ())))
            );
        }
        if ( rangeData.getLessThanOrEqual () != null ) {
            allFilters.add (Conditions.isLessOrEqualTo (column, SQL.literalOf (converterFunction.apply (rangeData.getLessThanOrEqual ()))));
        }
    }

    private <X> void buildGeneralConditions (BaseFilter<X> generalData, Column column, Class<?> targetClass) {
        Function<X, String> converterFunction = this.<X>columnValueConverter(targetClass);
        addGeneralEqualsCondition(generalData, column, converterFunction);
        addGeneralNotEqualsCondition(generalData, column, converterFunction);
        addGeneralInCondition(generalData, column, converterFunction);
        addGeneralNotInCondition(generalData, column, converterFunction);
        addSpecifiedCondition(generalData, column);
    }

    private <X> void addGeneralEqualsCondition(BaseFilter<X> generalData, Column column, Function<X, String> converterFunction) {
        var value = generalData.getEquals();
        if (value != null) {
            allFilters.add(Conditions.isEqual(column, SQL.literalOf(converterFunction.apply(value))));
        }
    }

    private <X> void addGeneralNotEqualsCondition(BaseFilter<X> generalData, Column column, Function<X, String> converterFunction) {
        var value = generalData.getNotEquals();
        if (value != null) {
            allFilters.add(Conditions.isNotEqual(column, SQL.literalOf(converterFunction.apply(value))));
        }
    }

    private <X> void addGeneralInCondition(BaseFilter<X> generalData, Column column, Function<X, String> converterFunction) {
        var values = generalData.getIn();
        if (values != null && !values.isEmpty()) {
            allFilters.add(
                    Conditions.in(
                            column,
                            values.stream()
                                    .map(eachIn -> SQL.literalOf(converterFunction.apply(eachIn)))
                                    .collect(Collectors.toList())
                    )
            );
        }
    }

    private <X> void addGeneralNotInCondition(BaseFilter<X> generalData, Column column, Function<X, String> converterFunction) {
        var values = generalData.getNotIn();
        if (values != null && !values.isEmpty()) {
            allFilters.add(
                    Conditions.notIn(
                            column,
                            values.stream()
                                    .map(eachNotIn -> SQL.literalOf(converterFunction.apply(eachNotIn)))
                                    .collect(Collectors.toList())
                    )
            );
        }
    }

    private <X> void addSpecifiedCondition(BaseFilter<X> generalData, Column column) {
        var specified = generalData.getSpecified();
        if (specified == null) {
            return;
        }
        allFilters.add(specified ? Conditions.isNull(column).not() : Conditions.isNull(column));
    }

    private void buildStringConditions (StrFilter stringData, Column column) {
        if ( stringData.getContains () != null ) {
            allFilters.add (Conditions.like (column, SQL.literalOf (stringData.getContains ())));
        }
        if ( stringData.getDoesNotContain () != null ) {
            allFilters.add (Conditions.notLike (column, SQL.literalOf (stringData.getDoesNotContain ())));
        }
    }

    private <X> void buildBooleanConditions (BaseFilter<X> generalData, Column column) {
        addBooleanEqualsCondition(generalData, column);
        addBooleanNotEqualsCondition(generalData, column);
        addBooleanInCondition(generalData, column);
        addBooleanNotInCondition(generalData, column);
        addBooleanSpecifiedCondition(generalData, column);
    }

    private <X> void addBooleanEqualsCondition(BaseFilter<X> generalData, Column column) {
        var value = generalData.getEquals();
        if (value != null) {
            allFilters.add(Conditions.isEqual(column, SQL.literalOf(columnConverter.convert(value, Boolean.class))));
        }
    }

    private <X> void addBooleanNotEqualsCondition(BaseFilter<X> generalData, Column column) {
        var value = generalData.getNotEquals();
        if (value != null) {
            allFilters.add(Conditions.isNotEqual(column, SQL.literalOf(columnConverter.convert(value, Boolean.class))));
        }
    }

    private <X> void addBooleanInCondition(BaseFilter<X> generalData, Column column) {
        var values = generalData.getIn();
        if (values != null && !values.isEmpty()) {
            allFilters.add(
                    Conditions.in(
                            column,
                            values.stream()
                                    .map(eachIn -> SQL.literalOf(columnConverter.convert(eachIn, Boolean.class)))
                                    .collect(Collectors.toList())
                    )
            );
        }
    }

    private <X> void addBooleanNotInCondition(BaseFilter<X> generalData, Column column) {
        var values = generalData.getNotIn();
        if (values != null && !values.isEmpty()) {
            allFilters.add(
                    Conditions.notIn(
                            column,
                            values.stream()
                                    .map(eachNotIn -> SQL.literalOf(columnConverter.convert(eachNotIn, Boolean.class)))
                                    .collect(Collectors.toList())
                    )
            );
        }
    }

    private <X> void addBooleanSpecifiedCondition(BaseFilter<X> generalData, Column column) {
        var specified = generalData.getSpecified();
        if (specified == null) {
            return;
        }
        allFilters.add(specified ? Conditions.isNull(column).not() : Conditions.isNull(column));
    }

    private <X> Function<X, String> columnValueConverter (Class<?> targetClass) {
        if ( targetClass != null ) {
            return value -> columnConverter.convert (value, targetClass).toString ();
        } else {
            return Object::toString;
        }
    }

    /**
     * Method that builds and returns the compounded Condition object. This method can be called
     * multiple times as the Conditions are being built.
     *
     * @return returns the compounded Condition object
     */
    public Condition buildConditions () {
        return allFilters
                .stream ()
                .reduce (null, (Condition cumulated, Condition eachCondition) -> {
                    return cumulated != null ? cumulated.and (eachCondition) : eachCondition;
                });
    }
}

package com.me.learning.customerservice.controller;

import static io.restassured.module.mockmvc.RestAssuredMockMvc.given;
import static org.assertj.core.api.Assertions.assertThat;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.greaterThanOrEqualTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Locale;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;

import io.restassured.http.ContentType;
import io.restassured.module.mockmvc.RestAssuredMockMvc;

import com.me.learning.customerservice.dto.CustomerResponseDto;
import com.me.learning.customerservice.repository.CustomerRepository;

/**
 * Full-stack integration tests for {@link CustomerController}.
 *
 * <p>Uses <em>REST Assured spring-mock-mvc</em> — the same fluent
 * {@code given().when().then()} DSL but backed by Spring's {@link MockMvc}
 * rather than a real HTTP client.  This avoids Groovy-metaclass incompatibilities
 * with Java 25 while still exercising every layer (controller, service, mapper,
 * repository, H2 in-memory database).
 *
 * <h3>Test fixture strategy</h3>
 * <ul>
 *   <li>{@code @BeforeAll} – inserts a Country → City → Address hierarchy via
 *       {@link JdbcTemplate} (bypasses the {@code geometry NOT NULL} constraint
 *       that is otherwise difficult to satisfy via JPA alone).</li>
 *   <li>{@code @AfterEach} – deletes all Customer rows so every test starts
 *       with an empty customer table while keeping the shared address intact.</li>
 *   <li>{@code @AfterAll}  – removes the pre-seeded address / city / country
 *       rows in the correct FK order.</li>
 * </ul>
 *
 * <p>Note: with {@link AutoConfigureMockMvc} the {@code server.servlet.context-path}
 * is NOT prepended — test paths start directly at the controller mapping.
 */
@SpringBootTest
@AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@DisplayName("CustomerController — Integration Tests (MockMvc)")
@SuppressWarnings({"PMD.MethodNamingConventions", "PMD.UnitTestShouldIncludeAssert", "PMD.ClassNamingConventions"})
class CustomerControllerIT {

    /* ── Constants ─────────────────────────────────────────────────────── */

    /** Controller mapping — no context-path prefix needed with MockMvc. */
    private static final String CUSTOMERS_PATH = "/api/v1/customers";
    private static final String CREATE_DATE    = "2024-06-01T12:00:00Z";
    private static final int    UNKNOWN_ID     = 999_999;

    /* ── Spring injections ──────────────────────────────────────────────── */

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Autowired
    private CustomerRepository customerRepository;

    /* ── Shared fixture state ────────────────────────────────────────────── */

    private int addressId;

    /* ══════════════════════════════════════════════════════════════════════
       Fixture lifecycle
    ══════════════════════════════════════════════════════════════════════ */

    @BeforeAll
    void setUpSharedFixture() {
        // Configure REST Assured to use this test's MockMvc instance
        RestAssuredMockMvc.mockMvc(mockMvc);

        // ── Country ──────────────────────────────────────────────────────
        jdbcTemplate.update(
                "INSERT INTO country (country, last_update) VALUES (?, CURRENT_TIMESTAMP)",
                "TestLand");
        Integer countryId = jdbcTemplate.queryForObject(
                "SELECT country_id FROM country WHERE country = ?",
                Integer.class, "TestLand");

        // ── City ──────────────────────────────────────────────────────────
        jdbcTemplate.update(
                "INSERT INTO city (city, country_id, last_update) VALUES (?, ?, CURRENT_TIMESTAMP)",
                "TestCity", countryId);
        Integer cityId = jdbcTemplate.queryForObject(
                "SELECT city_id FROM city WHERE city = ?",
                Integer.class, "TestCity");

        // ── Address (geometry literal avoids JPA mapping friction) ────────
        jdbcTemplate.update(
                "INSERT INTO address (address, district, city_id, phone, location, last_update) "
                + "VALUES (?, ?, ?, ?, GEOMETRY 'POINT(0 0)', CURRENT_TIMESTAMP)",
                "1 Integration St", "TestDistrict", cityId, "555-0199");
        addressId = jdbcTemplate.queryForObject(
                "SELECT address_id FROM address WHERE address = ?",
                Integer.class, "1 Integration St");
    }

    @AfterEach
    void cleanUpCustomers() {
        customerRepository.deleteAll();
    }

    @AfterAll
    void tearDownSharedFixture() {
        jdbcTemplate.update("DELETE FROM address WHERE address = ?", "1 Integration St");
        jdbcTemplate.update("DELETE FROM city    WHERE city    = ?", "TestCity");
        jdbcTemplate.update("DELETE FROM country WHERE country = ?", "TestLand");
    }

    /* ══════════════════════════════════════════════════════════════════════
       Helpers
    ══════════════════════════════════════════════════════════════════════ */

    /**
     * Builds a minimal valid customer JSON payload.
     * Only the address {@code id} field is required by the service layer.
     */
    private String customerJson(String firstName, String lastName) {
        return "{\"firstName\":\"%s\",\"lastName\":\"%s\",\"email\":\"%s.%s@test.com\","
               + "\"active\":true,\"createDate\":\"%s\",\"address\":{\"id\":%d}}"
               .formatted(firstName, lastName,
                       firstName.toLowerCase(Locale.ROOT), lastName.toLowerCase(Locale.ROOT),
                       CREATE_DATE, addressId);
    }

    /**
     * Creates a customer via the API and returns its generated ID.
     */
    private int createCustomer(String firstName, String lastName) {
        return given()
                    .contentType(ContentType.JSON)
                    .body(customerJson(firstName, lastName))
               .when()
                    .post(CUSTOMERS_PATH)
               .then()
                    .statusCode(201)
                    .extract().jsonPath().getInt("id");
    }

    /* ══════════════════════════════════════════════════════════════════════
       POST /api/v1/customers
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("POST — valid payload returns 201 with populated body")
    void create_withValidPayload_returns201AndPopulatedBody() {
        given()
            .contentType(ContentType.JSON)
            .body(customerJson("Alice", "Wonderland"))
        .when()
            .post(CUSTOMERS_PATH)
        .then()
            .statusCode(201)
            .body("id",        notNullValue())
            .body("firstName", equalTo("Alice"))
            .body("lastName",  equalTo("Wonderland"))
            .body("email",     equalTo("alice.wonderland@test.com"))
            .body("active",    equalTo(true))
            .body("addressId", equalTo(addressId));
    }

    @Test
    @DisplayName("POST — missing required fields returns 400")
    void create_withMissingRequiredFields_returns400() {
        given()
            .contentType(ContentType.JSON)
            .body("{\"email\":\"nobody@test.com\",\"active\":true}")
        .when()
            .post(CUSTOMERS_PATH)
        .then()
            .statusCode(400);
    }

    @Test
    @DisplayName("POST — non-existent address ID returns 404")
    void create_withNonExistentAddress_returns404() {
        String json = "{\"firstName\":\"Ghost\",\"lastName\":\"Address\",\"active\":true,"
                    + "\"createDate\":\"" + CREATE_DATE + "\","
                    + "\"address\":{\"id\":" + UNKNOWN_ID + "}}";

        int status =
            given()
                .contentType(ContentType.JSON)
                .body(json)
            .when()
                .post(CUSTOMERS_PATH)
            .then()
                .extract().statusCode();

        assertThat(status).isEqualTo(404);
    }

    /* ══════════════════════════════════════════════════════════════════════
       GET /api/v1/customers/{id}
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("GET /{id} — existing customer returns 200 with correct data")
    void findById_whenCustomerExists_returns200WithData() {
        int customerId = createCustomer("Bob", "Builder");

        CustomerResponseDto response =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/{id}", customerId)
            .then()
                .statusCode(200)
                .extract().as(CustomerResponseDto.class);

        assertThat(response.id()).isEqualTo(customerId);
        assertThat(response.firstName()).isEqualTo("Bob");
        assertThat(response.lastName()).isEqualTo("Builder");
        assertThat(response.active()).isTrue();
        assertThat(response.addressId()).isEqualTo(addressId);
    }

    @Test
    @DisplayName("GET /{id} — non-existent customer returns 404")
    void findById_whenCustomerNotFound_returns404() {
        int status =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/{id}", UNKNOWN_ID)
            .then()
                .extract().statusCode();

        assertThat(status).isEqualTo(404);
    }

    /* ══════════════════════════════════════════════════════════════════════
       GET /api/v1/customers  (paginated)
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("GET — paginated list returns 200 with customers in content array")
    void findAll_withStoredCustomers_returns200WithPageContent() {
        createCustomer("Charlie", "Chaplin");
        createCustomer("Diana", "Prince");

        given()
            .queryParam("page", 0)
            .queryParam("size", 10)
        .when()
            .get(CUSTOMERS_PATH)
        .then()
            .statusCode(200)
            .body("content.size()", greaterThanOrEqualTo(2))
            .body("totalElements",  greaterThanOrEqualTo(2));
    }

    /* ══════════════════════════════════════════════════════════════════════
       GET /api/v1/customers/all  (unpaged)
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("GET /all — returns 200 with all customers as a list")
    void findAll_unpaged_returns200AndList() {
        createCustomer("Eve", "Alien");
        createCustomer("Frank", "Sinatra");

        int totalSizeReturned =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/all")
            .then()
                .statusCode(200)
                .extract().jsonPath().getInt("$.size()");

        assertThat(totalSizeReturned).isGreaterThanOrEqualTo(2);
    }

    /* ══════════════════════════════════════════════════════════════════════
       PUT /api/v1/customers/{id}
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("PUT /{id} — full update returns 200 with new field values")
    void update_withValidPayload_returns200WithUpdatedFields() {
        int customerId = createCustomer("OldFirst", "OldLast");

        String updateJson = "{\"firstName\":\"NewFirst\",\"lastName\":\"NewLast\","
                          + "\"email\":\"new@test.com\",\"active\":false,"
                          + "\"createDate\":\"" + CREATE_DATE + "\","
                          + "\"address\":{\"id\":" + addressId + "}}";

        given()
            .contentType(ContentType.JSON)
            .body(updateJson)
        .when()
            .put(CUSTOMERS_PATH + "/{id}", customerId)
        .then()
            .statusCode(200)
            .body("id",        equalTo(customerId))
            .body("firstName", equalTo("NewFirst"))
            .body("lastName",  equalTo("NewLast"))
            .body("email",     equalTo("new@test.com"))
            .body("active",    equalTo(false));
    }

    @Test
    @DisplayName("PUT /{id} — non-existent customer returns 404")
    void update_whenCustomerNotFound_returns404() {
        int status =
            given()
                .contentType(ContentType.JSON)
                .body(customerJson("Ghost", "User"))
            .when()
                .put(CUSTOMERS_PATH + "/{id}", UNKNOWN_ID)
            .then()
                .extract().statusCode();

        assertThat(status).isEqualTo(404);
    }

    /* ══════════════════════════════════════════════════════════════════════
       PATCH /api/v1/customers/{id}
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("PATCH /{id} — partial update returns 200 with only changed fields modified")
    void partialUpdate_withPartialPayload_returns200WithChangedField() {
        int customerId = createCustomer("PatchFirst", "PatchLast");

        given()
            .contentType(ContentType.JSON)
            .body("{\"firstName\":\"PatchedFirst\"}")
        .when()
            .patch(CUSTOMERS_PATH + "/{id}", customerId)
        .then()
            .statusCode(200)
            .body("id",        equalTo(customerId))
            .body("firstName", equalTo("PatchedFirst"))
            .body("lastName",  equalTo("PatchLast"));  // unchanged
    }

    @Test
    @DisplayName("PATCH /{id} — non-existent customer returns 404")
    void partialUpdate_whenCustomerNotFound_returns404() {
        int status =
            given()
                .contentType(ContentType.JSON)
                .body("{\"firstName\":\"Ghost\"}")
            .when()
                .patch(CUSTOMERS_PATH + "/{id}", UNKNOWN_ID)
            .then()
                .extract().statusCode();

        assertThat(status).isEqualTo(404);
    }

    /* ══════════════════════════════════════════════════════════════════════
       DELETE /api/v1/customers/{id}
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("DELETE /{id} — existing customer returns 204 and is no longer retrievable")
    void delete_whenCustomerExists_returns204AndCustomerIsGone() {
        int customerId = createCustomer("ToDelete", "User");

        int deleteStatus =
            given()
            .when()
                .delete(CUSTOMERS_PATH + "/{id}", customerId)
            .then()
                .extract().statusCode();

        assertThat(deleteStatus).isEqualTo(204);

        // Confirm customer is no longer retrievable
        int getStatus =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/{id}", customerId)
            .then()
                .extract().statusCode();

        assertThat(getStatus).isEqualTo(404);
    }

    @Test
    @DisplayName("DELETE /{id} — non-existent customer returns 404")
    void delete_whenCustomerNotFound_returns404() {
        int status =
            given()
            .when()
                .delete(CUSTOMERS_PATH + "/{id}", UNKNOWN_ID)
            .then()
                .extract().statusCode();

        assertThat(status).isEqualTo(404);
    }

    /* ══════════════════════════════════════════════════════════════════════
       GET /api/v1/customers/count
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("GET /count — returns 200 with the total number of customers")
    void count_returns200WithCustomerCount() {
        createCustomer("Count", "One");
        createCustomer("Count", "Two");

        int count =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/count")
            .then()
                .statusCode(200)
                .extract().as(Integer.class);

        assertThat(count).isGreaterThanOrEqualTo(2);
    }

    /* ══════════════════════════════════════════════════════════════════════
       GET /api/v1/customers/exists/{id}
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("GET /exists/{id} — returns true for existing customer")
    void existsById_whenCustomerExists_returnsTrue() {
        int customerId = createCustomer("Exists", "Check");

        Boolean exists =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/exists/{id}", customerId)
            .then()
                .statusCode(200)
                .extract().as(Boolean.class);

        assertThat(exists).isTrue();
    }

    @Test
    @DisplayName("GET /exists/{id} — returns false for non-existent customer")
    void existsById_whenCustomerAbsent_returnsFalse() {
        Boolean exists =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/exists/{id}", UNKNOWN_ID)
            .then()
                .statusCode(200)
                .extract().as(Boolean.class);

        assertThat(exists).isFalse();
    }
}

package com.me.learning.customerservice.controller;

import static io.restassured.module.mockmvc.RestAssuredMockMvc.given;
import static org.assertj.core.api.Assertions.assertThat;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.greaterThanOrEqualTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Locale;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.web.context.WebApplicationContext;

import io.restassured.http.ContentType;
import io.restassured.module.mockmvc.RestAssuredMockMvc;

import com.me.learning.customerservice.dto.CustomerResponseDto;
import com.me.learning.customerservice.repository.CustomerRepository;

/**
 * Full-stack integration tests for {@link CustomerController}.
 *
 * <p>Uses <em>REST Assured spring-mock-mvc</em> — the same fluent
 * {@code given().when().then()} DSL but backed by Spring's {@link MockMvc}
 * rather than a real HTTP client.  This avoids Groovy-metaclass incompatibilities
 * with Java 25 while still exercising every layer (controller, service, mapper,
 * repository, H2 in-memory database).
 *
 * <h3>Test fixture strategy</h3>
 * <ul>
 *   <li>{@code @BeforeAll} – inserts a Country → City → Address hierarchy via
 *       {@link JdbcTemplate} (bypasses the {@code geometry NOT NULL} constraint
 *       that is otherwise difficult to satisfy via JPA alone).</li>
 *   <li>{@code @AfterEach} – deletes all Customer rows so every test starts
 *       with an empty customer table while keeping the shared address intact.</li>
 *   <li>{@code @AfterAll}  – removes the pre-seeded address / city / country
 *       rows in the correct FK order.</li>
 * </ul>
 *
 * <p>Note: with {@link AutoConfigureMockMvc} the {@code server.servlet.context-path}
 * is NOT prepended — test paths start directly at the controller mapping.
 */
@SpringBootTest
@AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@DisplayName("CustomerController — Integration Tests (MockMvc)")
@SuppressWarnings({"PMD.MethodNamingConventions", "PMD.UnitTestShouldIncludeAssert", "PMD.ClassNamingConventions"})
class CustomerControllerIT {

    /* ── Constants ─────────────────────────────────────────────────────── */

    /** Controller mapping — no context-path prefix needed with MockMvc. */
    private static final String CUSTOMERS_PATH = "/api/v1/customers";
    private static final String CREATE_DATE    = "2024-06-01T12:00:00Z";
    private static final int    UNKNOWN_ID     = 999_999;

    /* ── Spring injections ──────────────────────────────────────────────── */

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Autowired
    private CustomerRepository customerRepository;

    /* ── Shared fixture state ────────────────────────────────────────────── */

    private int addressId;

    /* ══════════════════════════════════════════════════════════════════════
       Fixture lifecycle
    ══════════════════════════════════════════════════════════════════════ */

    @BeforeAll
    void setUpSharedFixture() {
        // Configure REST Assured to use this test's MockMvc instance
        RestAssuredMockMvc.mockMvc(mockMvc);

        // ── Country ──────────────────────────────────────────────────────
        jdbcTemplate.update(
                "INSERT INTO country (country, last_update) VALUES (?, CURRENT_TIMESTAMP)",
                "TestLand");
        Integer countryId = jdbcTemplate.queryForObject(
                "SELECT country_id FROM country WHERE country = ?",
                Integer.class, "TestLand");

        // ── City ──────────────────────────────────────────────────────────
        jdbcTemplate.update(
                "INSERT INTO city (city, country_id, last_update) VALUES (?, ?, CURRENT_TIMESTAMP)",
                "TestCity", countryId);
        Integer cityId = jdbcTemplate.queryForObject(
                "SELECT city_id FROM city WHERE city = ?",
                Integer.class, "TestCity");

        // ── Address (geometry literal avoids JPA mapping friction) ────────
        jdbcTemplate.update(
                "INSERT INTO address (address, district, city_id, phone, location, last_update) "
                + "VALUES (?, ?, ?, ?, GEOMETRY 'POINT(0 0)', CURRENT_TIMESTAMP)",
                "1 Integration St", "TestDistrict", cityId, "555-0199");
        addressId = jdbcTemplate.queryForObject(
                "SELECT address_id FROM address WHERE address = ?",
                Integer.class, "1 Integration St");
    }

    @AfterEach
    void cleanUpCustomers() {
        customerRepository.deleteAll();
    }

    @AfterAll
    void tearDownSharedFixture() {
        jdbcTemplate.update("DELETE FROM address WHERE address = ?", "1 Integration St");
        jdbcTemplate.update("DELETE FROM city    WHERE city    = ?", "TestCity");
        jdbcTemplate.update("DELETE FROM country WHERE country = ?", "TestLand");
    }

    /* ══════════════════════════════════════════════════════════════════════
       Helpers
    ══════════════════════════════════════════════════════════════════════ */

    /**
     * Builds a minimal valid customer JSON payload.
     * Only the address {@code id} field is required by the service layer.
     */
    private String customerJson(String firstName, String lastName) {
        return "{\"firstName\":\"%s\",\"lastName\":\"%s\",\"email\":\"%s.%s@test.com\","
               + "\"active\":true,\"createDate\":\"%s\",\"address\":{\"id\":%d}}"
               .formatted(firstName, lastName,
                       firstName.toLowerCase(Locale.ROOT), lastName.toLowerCase(Locale.ROOT),
                       CREATE_DATE, addressId);
    }

    /**
     * Creates a customer via the API and returns its generated ID.
     */
    private int createCustomer(String firstName, String lastName) {
        return given()
                    .contentType(ContentType.JSON)
                    .body(customerJson(firstName, lastName))
               .when()
                    .post(CUSTOMERS_PATH)
               .then()
                    .statusCode(201)
                    .extract().jsonPath().getInt("id");
    }

    /* ══════════════════════════════════════════════════════════════════════
       POST /api/v1/customers
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("POST — valid payload returns 201 with populated body")
    void create_withValidPayload_returns201AndPopulatedBody() {
        given()
            .contentType(ContentType.JSON)
            .body(customerJson("Alice", "Wonderland"))
        .when()
            .post(CUSTOMERS_PATH)
        .then()
            .statusCode(201)
            .body("id",        notNullValue())
            .body("firstName", equalTo("Alice"))
            .body("lastName",  equalTo("Wonderland"))
            .body("email",     equalTo("alice.wonderland@test.com"))
            .body("active",    equalTo(true))
            .body("addressId", equalTo(addressId));
    }

    @Test
    @DisplayName("POST — missing required fields returns 400")
    void create_withMissingRequiredFields_returns400() {
        given()
            .contentType(ContentType.JSON)
            .body("{\"email\":\"nobody@test.com\",\"active\":true}")
        .when()
            .post(CUSTOMERS_PATH)
        .then()
            .statusCode(400);
    }

    @Test
    @DisplayName("POST — non-existent address ID returns 404")
    void create_withNonExistentAddress_returns404() {
        String json = "{\"firstName\":\"Ghost\",\"lastName\":\"Address\",\"active\":true,"
                    + "\"createDate\":\"" + CREATE_DATE + "\","
                    + "\"address\":{\"id\":" + UNKNOWN_ID + "}}";

        int status =
            given()
                .contentType(ContentType.JSON)
                .body(json)
            .when()
                .post(CUSTOMERS_PATH)
            .then()
                .extract().statusCode();

        assertThat(status).isEqualTo(404);
    }

    /* ══════════════════════════════════════════════════════════════════════
       GET /api/v1/customers/{id}
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("GET /{id} — existing customer returns 200 with correct data")
    void findById_whenCustomerExists_returns200WithData() {
        int customerId = createCustomer("Bob", "Builder");

        CustomerResponseDto response =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/{id}", customerId)
            .then()
                .statusCode(200)
                .extract().as(CustomerResponseDto.class);

        assertThat(response.id()).isEqualTo(customerId);
        assertThat(response.firstName()).isEqualTo("Bob");
        assertThat(response.lastName()).isEqualTo("Builder");
        assertThat(response.active()).isTrue();
        assertThat(response.addressId()).isEqualTo(addressId);
    }

    @Test
    @DisplayName("GET /{id} — non-existent customer returns 404")
    void findById_whenCustomerNotFound_returns404() {
        int status =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/{id}", UNKNOWN_ID)
            .then()
                .extract().statusCode();

        assertThat(status).isEqualTo(404);
    }

    /* ══════════════════════════════════════════════════════════════════════
       GET /api/v1/customers  (paginated)
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("GET — paginated list returns 200 with customers in content array")
    void findAll_withStoredCustomers_returns200WithPageContent() {
        createCustomer("Charlie", "Chaplin");
        createCustomer("Diana", "Prince");

        given()
            .queryParam("page", 0)
            .queryParam("size", 10)
        .when()
            .get(CUSTOMERS_PATH)
        .then()
            .statusCode(200)
            .body("content.size()", greaterThanOrEqualTo(2))
            .body("totalElements",  greaterThanOrEqualTo(2));
    }

    /* ══════════════════════════════════════════════════════════════════════
       GET /api/v1/customers/all  (unpaged)
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("GET /all — returns 200 with all customers as a list")
    void findAll_unpaged_returns200AndList() {
        createCustomer("Eve", "Alien");
        createCustomer("Frank", "Sinatra");

        int totalSizeReturned =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/all")
            .then()
                .statusCode(200)
                .extract().jsonPath().getInt("$.size()");

        assertThat(totalSizeReturned).isGreaterThanOrEqualTo(2);
    }

    /* ══════════════════════════════════════════════════════════════════════
       PUT /api/v1/customers/{id}
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("PUT /{id} — full update returns 200 with new field values")
    void update_withValidPayload_returns200WithUpdatedFields() {
        int customerId = createCustomer("OldFirst", "OldLast");

        String updateJson = "{\"firstName\":\"NewFirst\",\"lastName\":\"NewLast\","
                          + "\"email\":\"new@test.com\",\"active\":false,"
                          + "\"createDate\":\"" + CREATE_DATE + "\","
                          + "\"address\":{\"id\":" + addressId + "}}";

        given()
            .contentType(ContentType.JSON)
            .body(updateJson)
        .when()
            .put(CUSTOMERS_PATH + "/{id}", customerId)
        .then()
            .statusCode(200)
            .body("id",        equalTo(customerId))
            .body("firstName", equalTo("NewFirst"))
            .body("lastName",  equalTo("NewLast"))
            .body("email",     equalTo("new@test.com"))
            .body("active",    equalTo(false));
    }

    @Test
    @DisplayName("PUT /{id} — non-existent customer returns 404")
    void update_whenCustomerNotFound_returns404() {
        int status =
            given()
                .contentType(ContentType.JSON)
                .body(customerJson("Ghost", "User"))
            .when()
                .put(CUSTOMERS_PATH + "/{id}", UNKNOWN_ID)
            .then()
                .extract().statusCode();

        assertThat(status).isEqualTo(404);
    }

    /* ══════════════════════════════════════════════════════════════════════
       PATCH /api/v1/customers/{id}
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("PATCH /{id} — partial update returns 200 with only changed fields modified")
    void partialUpdate_withPartialPayload_returns200WithChangedField() {
        int customerId = createCustomer("PatchFirst", "PatchLast");

        given()
            .contentType(ContentType.JSON)
            .body("{\"firstName\":\"PatchedFirst\"}")
        .when()
            .patch(CUSTOMERS_PATH + "/{id}", customerId)
        .then()
            .statusCode(200)
            .body("id",        equalTo(customerId))
            .body("firstName", equalTo("PatchedFirst"))
            .body("lastName",  equalTo("PatchLast"));  // unchanged
    }

    @Test
    @DisplayName("PATCH /{id} — non-existent customer returns 404")
    void partialUpdate_whenCustomerNotFound_returns404() {
        int status =
            given()
                .contentType(ContentType.JSON)
                .body("{\"firstName\":\"Ghost\"}")
            .when()
                .patch(CUSTOMERS_PATH + "/{id}", UNKNOWN_ID)
            .then()
                .extract().statusCode();

        assertThat(status).isEqualTo(404);
    }

    /* ══════════════════════════════════════════════════════════════════════
       DELETE /api/v1/customers/{id}
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("DELETE /{id} — existing customer returns 204 and is no longer retrievable")
    void delete_whenCustomerExists_returns204AndCustomerIsGone() {
        int customerId = createCustomer("ToDelete", "User");

        int deleteStatus =
            given()
            .when()
                .delete(CUSTOMERS_PATH + "/{id}", customerId)
            .then()
                .extract().statusCode();

        assertThat(deleteStatus).isEqualTo(204);

        // Confirm customer is no longer retrievable
        int getStatus =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/{id}", customerId)
            .then()
                .extract().statusCode();

        assertThat(getStatus).isEqualTo(404);
    }

    @Test
    @DisplayName("DELETE /{id} — non-existent customer returns 404")
    void delete_whenCustomerNotFound_returns404() {
        int status =
            given()
            .when()
                .delete(CUSTOMERS_PATH + "/{id}", UNKNOWN_ID)
            .then()
                .extract().statusCode();

        assertThat(status).isEqualTo(404);
    }

    /* ══════════════════════════════════════════════════════════════════════
       GET /api/v1/customers/count
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("GET /count — returns 200 with the total number of customers")
    void count_returns200WithCustomerCount() {
        createCustomer("Count", "One");
        createCustomer("Count", "Two");

        int count =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/count")
            .then()
                .statusCode(200)
                .extract().as(Integer.class);

        assertThat(count).isGreaterThanOrEqualTo(2);
    }

    /* ══════════════════════════════════════════════════════════════════════
       GET /api/v1/customers/exists/{id}
    ══════════════════════════════════════════════════════════════════════ */

    @Test
    @DisplayName("GET /exists/{id} — returns true for existing customer")
    void existsById_whenCustomerExists_returnsTrue() {
        int customerId = createCustomer("Exists", "Check");

        Boolean exists =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/exists/{id}", customerId)
            .then()
                .statusCode(200)
                .extract().as(Boolean.class);

        assertThat(exists).isTrue();
    }

    @Test
    @DisplayName("GET /exists/{id} — returns false for non-existent customer")
    void existsById_whenCustomerAbsent_returnsFalse() {
        Boolean exists =
            given()
            .when()
                .get(CUSTOMERS_PATH + "/exists/{id}", UNKNOWN_ID)
            .then()
                .statusCode(200)
                .extract().as(Boolean.class);

        assertThat(exists).isFalse();
    }
}

package com.me.learning.framework.service;
import java.time.Duration;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.Date;

import org.springframework.core.convert.converter.Converter;

public final class DateConverters {

    private DateConverters() {
    }

    public static final class LocalDateToDateConverter implements Converter<LocalDate, Date> {

        public static final LocalDateToDateConverter INSTANCE = new LocalDateToDateConverter();

        private LocalDateToDateConverter() {
        }

        @Override
        public Date convert(LocalDate source) {
            return source == null ? null : Date.from(source.atStartOfDay(ZoneId.systemDefault()).toInstant());
        }
    }

    public static final class DateToLocalDateConverter implements Converter<Date, LocalDate> {

        public static final DateToLocalDateConverter INSTANCE = new DateToLocalDateConverter();

        private DateToLocalDateConverter() {
        }

        @Override
        public LocalDate convert(Date source) {
            return source == null ? null : ZonedDateTime.ofInstant(source.toInstant(), ZoneId.systemDefault()).toLocalDate();
        }
    }

    public static final class ZonedDateTimeToDateConverter implements Converter<ZonedDateTime, Date> {

        public static final ZonedDateTimeToDateConverter INSTANCE = new ZonedDateTimeToDateConverter();

        private ZonedDateTimeToDateConverter() {
        }

        @Override
        public Date convert(ZonedDateTime source) {
            return source == null ? null : Date.from(source.toInstant());
        }
    }

    public static final class DateToZonedDateTimeConverter implements Converter<Date, ZonedDateTime> {

        public static final DateToZonedDateTimeConverter INSTANCE = new DateToZonedDateTimeConverter();

        private DateToZonedDateTimeConverter() {
        }

        @Override
        public ZonedDateTime convert(Date source) {
            return source == null ? null : ZonedDateTime.ofInstant(source.toInstant(), ZoneId.systemDefault());
        }
    }

    public static final class LocalDateTimeToDateConverter implements Converter<LocalDateTime, Date> {

        public static final LocalDateTimeToDateConverter INSTANCE = new LocalDateTimeToDateConverter();

        private LocalDateTimeToDateConverter() {
        }

        @Override
        public Date convert(LocalDateTime source) {
            return source == null ? null : Date.from(source.atZone(ZoneId.systemDefault()).toInstant());
        }
    }

    public static final class DateToLocalDateTimeConverter implements Converter<Date, LocalDateTime> {

        public static final DateToLocalDateTimeConverter INSTANCE = new DateToLocalDateTimeConverter();

        private DateToLocalDateTimeConverter() {
        }

        @Override
        public LocalDateTime convert(Date source) {
            return source == null ? null : LocalDateTime.ofInstant(source.toInstant(), ZoneId.systemDefault());
        }
    }

    public static final class DurationToLongConverter implements Converter<Duration, Long> {

        public static final DurationToLongConverter INSTANCE = new DurationToLongConverter();

        private DurationToLongConverter() {
        }

        @Override
        public Long convert(Duration source) {
            return source == null ? null : source.toNanos();
        }
    }

    public static final class LongToDurationConverter implements Converter<Long, Duration> {

        public static final LongToDurationConverter INSTANCE = new LongToDurationConverter();

        private LongToDurationConverter() {
        }

        @Override
        public Duration convert(Long source) {
            return source == null ? null : Duration.ofNanos(source);
        }
    }
}

