import java.text.MessageFormat;

import org.springframework.data.domain.Page;
import org.springframework.web.util.UriComponentsBuilder;


public class LinkHeaderUtil {


    private static final String HEADER_LINK_FORMAT = "<{0}>; rel=\"{1}\"";

    public String prepareLinkHeaders(UriComponentsBuilder uriBuilder, Page<?> page) {
        int pageNumber = page.getNumber();
        int pageSize = page.getSize();
        StringBuilder link = new StringBuilder();
        if (pageNumber < page.getTotalPages() - 1) {
            link.append(prepareLink(uriBuilder, pageNumber + 1, pageSize, "next")).append(',');
        }
        if (pageNumber > 0) {
            link.append(prepareLink(uriBuilder, pageNumber - 1, pageSize, "prev")).append(',');
        }
        link
                .append(prepareLink(uriBuilder, page.getTotalPages() - 1, pageSize, "last"))
                .append(',')
                .append(prepareLink(uriBuilder, 0, pageSize, "first"));
        return link.toString();
    }

    private static String prepareLink(UriComponentsBuilder uriBuilder, int pageNumber, int pageSize, String relType) {
        return MessageFormat.format(HEADER_LINK_FORMAT, preparePageUri(uriBuilder, pageNumber, pageSize), relType);
    }

    private static String preparePageUri(UriComponentsBuilder uriBuilder, int pageNumber, int pageSize) {
        return uriBuilder
                .replaceQueryParam("page", Integer.toString(pageNumber))
                .replaceQueryParam("size", Integer.toString(pageSize))
                .toUriString()
                .replace(",", "%2C")
                .replace(";", "%3B");
    }

}

package com.me.learning.parent.customerservice.config;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;

import lombok.extern.slf4j.Slf4j;

/**
 * Author   : Prabakaran Ramu
 * User     : ramup
 * Date     : 20/04/2026
 * Usage    : Interceptor for logging HTTP requests and responses
 * Since    : Version 1.0
 */
@Slf4j
@Component
public class LoggingInterceptor implements HandlerInterceptor {

    public static final int HTTP_STATUS_CODE_500 = 500;
    public static final int HTTP_STATUS_CODE_400 = 400;

    @Override
    public boolean preHandle (HttpServletRequest request, HttpServletResponse response, Object handler) {
        long startTime = System.currentTimeMillis ();
        request.setAttribute ("startTime", startTime);

        if ( log.isDebugEnabled () ) {
            log.debug ("\n============================ Request Begin ============================\nURI    : {}\nMethod : {}\nAddr   : {}",
                    request.getRequestURI (), request.getMethod (), request.getRemoteAddr ());
        }

        return true;
    }

    @Override
    public void afterCompletion (HttpServletRequest request, HttpServletResponse response,
                                 Object handler, Exception ex) {
        long startTime = (Long) request.getAttribute ("startTime");
        long executionTime = System.currentTimeMillis () - startTime;

        String logMessage = String.format (
                "\n=========================== Response Begin ============================\nURI    : %s\nMethod : %s\nStatus : %d\nTime   : %d ms",
                request.getRequestURI (), request.getMethod (), response.getStatus (), executionTime);

        if ( response.getStatus () >= HTTP_STATUS_CODE_500 ) {
            log.error (logMessage);
        } else if ( response.getStatus () >= HTTP_STATUS_CODE_400 ) {
            log.warn (logMessage);
        } else {
            log.info (logMessage);
        }

        if ( ex != null ) {
            log.error ("Request completed with exception: {}", ex.getMessage (), ex);
        }
    }
}

