public interface {{Entity}}Repository extends JpaRepository<{{Entity}}, Integer> {

    // Common derived query methods:
    Optional<{{Entity}}> findByNameIgnoreCase (String name);
    List<{{Entity}}> findByParentId (Integer parentId);
    boolean existsByNameIgnoreCase (String name);
}
