## 12. Step 10 — Service Interface Template

```java
package com.me.learning.parent.{{PKG}}.service;

import java.util.List;

import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;

import com.me.learning.parent.{{PKG}}.dto.{{Entity}}Request;
import com.me.learning.parent.{{PKG}}.dto.{{Entity}}Response;
import com.me.learning.parent.{{PKG}}.dto.{{Entity}}UpdateRequest;

/**
 * Author   : Prabakaran Ramu
 * User     : ramup
 * Date     : {{DATE}}
 * Usage    : Service interface for {{Entity}} entity operations
 * Since    : Version 1.0
 */
public interface {{Entity}}Service {

    {{Entity}}Response create{{Entity}} ({{Entity}}Request request);

    {{Entity}}Response update{{Entity}} (Integer id, {{Entity}}UpdateRequest request);

