```java
package com.me.learning.parent.{{PKG}}.service;

import java.util.List;

import org.springframework.cache.annotation.CacheEvict;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import com.me.learning.parent.{{PKG}}.dto.{{Entity}}Request;
import com.me.learning.parent.{{PKG}}.dto.{{Entity}}Response;
import com.me.learning.parent.{{PKG}}.dto.{{Entity}}UpdateRequest;
import com.me.learning.parent.{{PKG}}.entity.{{Entity}};
import com.me.learning.parent.{{PKG}}.exception.DuplicateResourceException;
import com.me.learning.parent.{{PKG}}.exception.ResourceNotFoundException;
import com.me.learning.parent.{{PKG}}.mapper.{{Entity}}Mapper;
import com.me.learning.parent.{{PKG}}.repository.{{Entity}}Repository;

/**
 * Author   : Prabakaran Ramu
 * ...
 */
@Slf4j
@Service
@RequiredArgsConstructor
@Transactional(readOnly = true)         // ALL reads are read-only by default
public class {{Entity}}ServiceImpl implements {{Entity}}Service {

    private static final String RESOURCE = "{{Entity}}";
    private static final String FIELD_ID = "id";
    private static final String FIELD_NAME = "name";

    private final {{Entity}}Repository repository;
    private final {{Entity}}Mapper mapper;

    @Override
    @Transactional                      // writes override readOnly
    @CacheEvict(value = {"{{entity}}s", "{{entity}}"}, allEntries = true)
    public {{Entity}}Response create{{Entity}} ({{Entity}}Request request) {
        log.debug("Creating {{entity}}: {}", request.name());

        if (repository.existsByNameIgnoreCase(request.name())) {
            throw new DuplicateResourceException(RESOURCE, FIELD_NAME, request.name());
        }

        {{Entity}} entity = mapper.toEntity(request);
        {{Entity}} saved = repository.save(entity);

        log.info("Created {{entity}} with ID: {}", saved.getId());
        return mapper.toResponse(saved);
    }

    @Override
    @Transactional
    @CacheEvict(value = {"{{entity}}s", "{{entity}}"}, allEntries = true)
    public {{Entity}}Response update{{Entity}} (Integer id, {{Entity}}UpdateRequest request) {
        log.debug("Updating {{entity}} with ID: {}", id);

        {{Entity}} existing = repository.findById(id)
            .orElseThrow(() -> new ResourceNotFoundException(RESOURCE, FIELD_ID, id));

        // ... full field update
        existing.setName(request.name());
        {{Entity}} updated = repository.save(existing);

        log.info("Updated {{entity}} with ID: {}", id);
        return mapper.toResponse(updated);
    }

    @Override
    @Transactional
    @CacheEvict(value = {"{{entity}}s", "{{entity}}"}, allEntries = true)
    public {{Entity}}Response patch{{Entity}} (Integer id, {{Entity}}UpdateRequest request) {
        {{Entity}} existing = repository.findById(id)
            .orElseThrow(() -> new ResourceNotFoundException(RESOURCE, FIELD_ID, id));

        mapper.updateEntity(request, existing);   // NullValuePropertyMappingStrategy.IGNORE
        return mapper.toResponse(repository.save(existing));
    }

    @Override
    public {{Entity}}Response get{{Entity}}ById (Integer id) {
        return mapper.toResponse(
            repository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException(RESOURCE, FIELD_ID, id))
        );
    }

    @Override
    public List<{{Entity}}Response> getAll{{Entity}}s () {
        return mapper.toResponseList(repository.findAll());
    }

    @Override
    public Page<{{Entity}}Response> getAll{{Entity}}s (Pageable pageable) {
        return repository.findAll(pageable).map(mapper::toResponse);
    }

    @Override
    @Transactional
    @CacheEvict(value = {"{{entity}}s", "{{entity}}"}, allEntries = true)
    public void delete{{Entity}} (Integer id) {
        if (!repository.existsById(id)) {
            throw new ResourceNotFoundException(RESOURCE, FIELD_ID, id);
        }
        repository.deleteById(id);
        log.info("Deleted {{entity}} with ID: {}", id);
    }

    @Override
    public boolean existsById (Integer id) { return repository.existsById(id); }

    @Override
    public long count{{Entity}}s () { return repository.count(); }
}
```

