## 16. Quick-Start PowerShell Script

Save as `New-SakilaModule.ps1` at the project root.

```powershell
# ============================================================
# New-SakilaModule.ps1
# Usage: .\New-SakilaModule.ps1 -ServiceName "film-service" -Port 8091 -Pkg "filmservice"
# ============================================================
param(
    [Parameter(Mandatory)][string]$ServiceName,
    [Parameter(Mandatory)][int]$Port,
    [Parameter(Mandatory)][string]$Pkg
)

$Root       = $PSScriptRoot
$SvcRoot    = Join-Path $Root $ServiceName
$JavaBase   = "com\me\learning\parent\$Pkg"
$JavaSrc    = Join-Path $SvcRoot "src\main\java\$JavaBase"
$JavaTest   = Join-Path $SvcRoot "src\test\java\$JavaBase"
$Resources  = Join-Path $SvcRoot "src\main\resources"

# --- Create directory tree ----------------------------------
@("config","controller","dto","entity","exception","mapper","repository","service") |
    ForEach-Object { New-Item -ItemType Directory -Force -Path (Join-Path $JavaSrc $_) | Out-Null }
New-Item -ItemType Directory -Force -Path $JavaTest  | Out-Null
New-Item -ItemType Directory -Force -Path $Resources | Out-Null

# --- Copy Maven wrapper from customer-service ---------------
$Ref = Join-Path $Root "customer-service"
Copy-Item (Join-Path $Ref "mvnw")     $SvcRoot -Force
Copy-Item (Join-Path $Ref "mvnw.cmd") $SvcRoot -Force
Copy-Item (Join-Path $Ref ".mvn") (Join-Path $SvcRoot ".mvn") -Recurse -Force

# --- application.yaml ---------------------------------------
$AppYaml = @"
spring:
  application:
    name: $ServiceName
  datasource:
    url: jdbc:mysql://localhost:3306/sakila?useSSL=false&serverTimezone=UTC&allowPublicKeyRetrieval=true
    username: root
    password: Oman@2017
    driver-class-name: com.mysql.cj.jdbc.Driver
  jpa:
    hibernate:
      ddl-auto: validate
    show-sql: true
    properties:
      hibernate:
        dialect: org.hibernate.dialect.MySQLDialect
        format_sql: true
server:
  port: $Port
springdoc:
  api-docs:
    path: /v3/api-docs
  swagger-ui:
    path: /swagger-ui.html
    enabled: true
logging:
  level:
    com.me.learning.parent.${Pkg}: INFO
"@
[System.IO.File]::WriteAllText((Join-Path $Resources "application.yaml"), $AppYaml,
    [System.Text.UTF8Encoding]::new($false))

# --- Copy exception & config classes from customer-service --
$CsSrc = Join-Path $Root "customer-service\src\main\java\com\me\learning\parent\customerservice"
$OldPkg = "com.me.learning.parent.customerservice"
$NewPkg = "com.me.learning.parent.$Pkg"

@("exception\ResourceNotFoundException.java",
  "exception\DuplicateResourceException.java",
  "exception\InvalidRequestException.java",
  "exception\ServiceException.java",
  "exception\GlobalExceptionHandler.java",
  "config\LoggingInterceptor.java",
  "config\WebMvcConfig.java") | ForEach-Object {
    $Content = (Get-Content (Join-Path $CsSrc $_) -Raw) -replace [regex]::Escape($OldPkg), $NewPkg
    [System.IO.File]::WriteAllText((Join-Path $JavaSrc $_), $Content,
        [System.Text.UTF8Encoding]::new($false))
}

# --- Scaffold CacheConfig & OpenAPIConfig -------------------
$CacheConfig = @"
package $NewPkg.config;

import org.springframework.cache.CacheManager;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.cache.concurrent.ConcurrentMapCacheManager;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
@EnableCaching
public class CacheConfig {

    @Bean
    public CacheManager cacheManager () {
        // TODO: add cache names for each entity
        return new ConcurrentMapCacheManager ("items", "item");
    }
}
"@
[System.IO.File]::WriteAllText((Join-Path $JavaSrc "config\CacheConfig.java"), $CacheConfig,
    [System.Text.UTF8Encoding]::new($false))

$OpenAPI = @"
package $NewPkg.config;

import java.util.List;

import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.info.Contact;
