        Info info = new Info ()
                .title ("$ServiceName API")
                .version ("1.0.0")
                .contact (contact)
                .description ("REST API for $ServiceName")
                .license (license);

        return new OpenAPI ()
                .info (info)
                .servers (List.of (localServer));
