}
"@
[System.IO.File]::WriteAllText((Join-Path $JavaSrc "config\OpenAPIConfig.java"), $OpenAPI,
    [System.Text.UTF8Encoding]::new($false))

# --- Generate Application main class ------------------------
$ClassName = ($ServiceName -split '-' | ForEach-Object { (Get-Culture).TextInfo.ToTitleCase($_) }) -join ''
$AppClass = @"
