### Generate a single entity scaffold

Add this function and call it after the module is created:

```powershell
function Generate-EntityFiles {
    param(
        [string]$SvcRoot,       # e.g. C:\...\film-service
        [string]$Pkg,           # e.g. filmservice
        [string]$Entity,        # e.g. Film  (PascalCase)
        [string]$IdType = "Integer"  # Integer or Short
    )

    $NewPkg   = "com.me.learning.parent.$Pkg"
    $JavaSrc  = Join-Path $SvcRoot "src\main\java\com\me\learning\parent\$Pkg"
    $entity   = $Entity.Substring(0,1).ToLower() + $Entity.Substring(1)
    $entities = $entity + "s"

    # --- DTO: Request ---
    $req = @"
package $NewPkg.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

public record ${Entity}Request(

        @NotBlank(message = "Name must not be blank")
        @Size(max = 50, message = "Name must not exceed 50 characters")
        String name

) {
}
"@
    # --- DTO: UpdateRequest ---
    $upd = @"
package $NewPkg.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

public record ${Entity}UpdateRequest(

        @NotBlank(message = "Name must not be blank")
        @Size(max = 50, message = "Name must not exceed 50 characters")
        String name

) {
}
"@
    # --- DTO: Response ---
    $rsp = @"
package $NewPkg.dto;

import java.time.Instant;

public record ${Entity}Response(

        $IdType id,
        String name,
        Instant lastUpdate

) {
}
"@
    # --- Mapper ---
    $mapper = @"
package $NewPkg.mapper;

import java.util.List;

import org.mapstruct.BeanMapping;
import org.mapstruct.Mapper;
import org.mapstruct.MappingTarget;
import org.mapstruct.NullValuePropertyMappingStrategy;
import org.mapstruct.ReportingPolicy;

import $NewPkg.dto.${Entity}Request;
import $NewPkg.dto.${Entity}Response;
import $NewPkg.dto.${Entity}UpdateRequest;
import $NewPkg.entity.${Entity};

@Mapper(componentModel = "spring", unmappedTargetPolicy = ReportingPolicy.IGNORE)
public interface ${Entity}Mapper {

    ${Entity} toEntity (${Entity}Request request);

    ${Entity}Response toResponse (${Entity} entity);

    List<${Entity}Response> toResponseList (List<${Entity}> entities);

    @BeanMapping(nullValuePropertyMappingStrategy = NullValuePropertyMappingStrategy.IGNORE)
    void updateEntity (${Entity}UpdateRequest request, @MappingTarget ${Entity} entity);
}
"@
    # --- Repository ---
    $repo = @"
package $NewPkg.repository;

import java.util.Optional;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

import $NewPkg.entity.${Entity};

@Repository
public interface ${Entity}Repository extends JpaRepository<${Entity}, $IdType> {

    Optional<${Entity}> findByNameIgnoreCase (String name);

    boolean existsByNameIgnoreCase (String name);
}
"@
    # --- Service Interface ---
    $svc = @"
package $NewPkg.service;

import java.util.List;

import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;

import $NewPkg.dto.${Entity}Request;
import $NewPkg.dto.${Entity}Response;
import $NewPkg.dto.${Entity}UpdateRequest;

public interface ${Entity}Service {

    ${Entity}Response create${Entity} (${Entity}Request request);
    ${Entity}Response update${Entity} ($IdType id, ${Entity}UpdateRequest request);
    ${Entity}Response patch${Entity} ($IdType id, ${Entity}UpdateRequest request);
    ${Entity}Response get${Entity}ById ($IdType id);
    List<${Entity}Response> getAll${Entity}s ();
    Page<${Entity}Response> getAll${Entity}s (Pageable pageable);
    void delete${Entity} ($IdType id);
    boolean existsById ($IdType id);
    long count${Entity}s ();
}
"@
    # Write all files
    $files = @{
        "dto\${Entity}Request.java"        = $req
        "dto\${Entity}UpdateRequest.java"  = $upd
        "dto\${Entity}Response.java"       = $rsp
        "mapper\${Entity}Mapper.java"      = $mapper
        "repository\${Entity}Repository.java" = $repo
        "service\${Entity}Service.java"    = $svc
    }
    foreach ($entry in $files.GetEnumerator()) {
        [System.IO.File]::WriteAllText(
            (Join-Path $JavaSrc $entry.Key),
            $entry.Value,
            [System.Text.UTF8Encoding]::new($false))
    }

    Write-Host "✅  Scaffolded: $Entity (dto + mapper + repository + service interface)" -ForegroundColor Green
    Write-Host "   ⚠️  Still needed manually:" -ForegroundColor Yellow
    Write-Host "      - entity/${Entity}.java  (add @Entity fields)"
    Write-Host "      - service/${Entity}ServiceImpl.java  (implement business logic)"
    Write-Host "      - controller/${Entity}Controller.java  (REST endpoints)"
}

# Example call:
# Generate-EntityFiles -SvcRoot "C:\...\film-service" -Pkg "filmservice" -Entity "Film"
```

